  for (const piece of ribbon(SKIRT_X0, SKIRT_X1, TOP_RAIL, BOT_RAIL)) SKIRT_PARTS.push(part(piece, "mid"));
  /* the outer face's own joints: a vertical every tread, and a mid rail */
  for (let station = 0; station <= STEPS + 2; station++) {
